'use strict';
import {
  adapterFun,
  changesHandler,
  processRevsRevsInfo,
} from 'pouchdb-utils';

import {
  collectLeaves,
  rootToLeaf,
  collectConflicts,
  isDeleted,
  isLocalId,
  latest as getLatest,
} from 'pouchdb-merge';

import {
  INVALID_ID,
  UNKNOWN_ERROR,
  INVALID_REV,
  createError
} from 'pouchdb-errors';

import setup from './setup';

// API implementations
import info from './info';
import get from './get';
import getAttachment from './getAttachment';
import bulkDocs from './bulkDocs';
import allDocs from './allDocs';
import changes from './changes';
import getRevisionTree from './getRevisionTree';
import doCompaction from './doCompaction';
import destroy from './destroy';
import {query, viewCleanup} from './find';
import purge from './purge';

import { DOC_STORE, idbError } from './util';

var ADAPTER_NAME = 'indexeddb';

// TODO: Constructor should be capitalised
var idbChanges = new changesHandler();

// A shared list of database handles
var openDatabases = {};

function IndexeddbPouch(dbOpts, callback) {

  if (dbOpts.view_adapter) {
    console.log('Please note that the indexeddb adapter manages _find indexes itself, therefore it is not using your specified view_adapter');
  }

  var api = this;
  var metadata = {};

  // Wrapper that gives you an active DB handle. You probably want $t.
  var $ = function (fun) {
    return function () {
      var args = Array.prototype.slice.call(arguments);
      setup(openDatabases, api, dbOpts).then(function (res) {
        metadata = res.metadata;
        args.unshift(res.idb);
        fun.apply(api, args);
      }).catch(function (err) {
        var last = args.pop();
        if (typeof last === 'function') {
          last(err);
        } else {
          console.error(err);
        }
      });
    };
  };
  // the promise version of $
  var $p = function (fun) {
    return function () {
      var args = Array.prototype.slice.call(arguments);

      return setup(openDatabases, api, dbOpts).then(function (res) {
        metadata = res.metadata;
        args.unshift(res.idb);

        return fun.apply(api, args);
      });
    };
  };
  // Wrapper that gives you a safe transaction handle. It's important to use
  // this instead of opening your own transaction from a db handle got from $,
  // because in the time between getting the db handle and opening the
  // transaction it may have been invalidated by index changes.
  var $t = function (fun, stores, mode) {
    stores = stores || [DOC_STORE];
    mode = mode || 'readonly';

    return function () {
      var args = Array.prototype.slice.call(arguments);
      var txn = {};
      setup(openDatabases, api, dbOpts).then(function (res) {
        metadata = res.metadata;
        txn.txn = res.idb.transaction(stores, mode);
      }).catch(function (err) {
        console.error('Failed to establish transaction safely');
        console.error(err);
        txn.error = err;
      }).then(function () {
        args.unshift(txn);
        fun.apply(api, args);
      });
    };
  };

  api._openTransactionSafely = function (stores, mode, callback) {
    $t(function (txn, callback) {
      callback(txn.error, txn.txn);
    }, stores, mode)(callback);
  };

  api._remote = false;
  api.type = function () { return ADAPTER_NAME; };

  api._id = $(function (_, cb) {
    cb(null, metadata.db_uuid);
  });

  api._info = $(function (_, cb) {
    return info(metadata, cb);
  });

  api._get = $t(get);

  api._bulkDocs = $(function (_, req, opts, callback) {
    bulkDocs(api, req, opts, metadata, dbOpts, idbChanges, callback);
  });

  api._allDocs = $t(function (txn, opts, cb) {
    allDocs(txn, metadata, opts, cb);
  });

  api._getAttachment = getAttachment;

  api._changes = $t(function (txn, opts) {
    changes(txn, idbChanges, api, dbOpts, opts);
  });

  api._getRevisionTree = $t(getRevisionTree);
  api._doCompaction = $t(doCompaction, [DOC_STORE], 'readwrite');

  api._customFindAbstractMapper = {
    query: $p(query),
    viewCleanup: $p(viewCleanup)
  };

  api._destroy = function (opts, callback) {
    return destroy(dbOpts, openDatabases, idbChanges, callback);
  };

  api._close = $(function (db, cb) {
    delete openDatabases[dbOpts.name];
    db.close();
    cb();
  });

  // Closing and re-opening the DB re-generates native indexes
  api._freshen = function () {
    return new Promise(function (resolve) {
      api._close(function () {
        $(resolve)();
      });
    });
  };

  api._purge = $t(purge, [DOC_STORE], 'readwrite');

  api.get = adapterFun('get', function (id, opts, cb) {
    console.log('api.get()', 'id:', id, 'opts:', JSON.stringify(opts), 'cb:', typeof cb);
    if (typeof opts === 'function') {
      cb = opts;
      opts = {};
    }
    opts = opts || {};
    if (typeof id !== 'string') {
      return cb(createError(INVALID_ID));
    }
    if (isLocalId(id) && typeof api._getLocal === 'function') {
      return api._getLocal(id, cb);
    }
    var leaves = [];

    let mySpecialDoc;

    const finishOpenRevs = () => {
      console.log('finishOpenRevs()', 'mySpecialDoc:', JSON.stringify(mySpecialDoc, null, 2));
      console.log('finishOpenRevs()', 'leaves:', JSON.stringify(leaves, null, 2));
      var result = [];
      var count = leaves.length;
      /* istanbul ignore if */
      if (!count) {
        console.log('finishOpenRevs()', 'returning: no count');
        return cb(null, result);
      }

      const myResult = [];
      const seen = new Map();
      for (let i=leaves.length-1; i>=0; --i) {
        const leaf = leaves[i];

        const rev = opts.latest ? getLatest(leaf, mySpecialDoc) : leaf;
        if (seen.has(rev)) {
          continue;
        }
        seen.set(rev);

        if (!(rev in mySpecialDoc.revs)) {
          myResult.push({ TODO:'missing' });
        } else {
          const result = mySpecialDoc.revs[rev].data;
          result._id = mySpecialDoc.id;
          result._rev = rev;

          if (isDeleted(mySpecialDoc, rev)) {
            result._deleted = true;
          }

          if (opts.revs) {
            processRevsRevsInfo(id, result, mySpecialDoc.rev_tree, opts);
          }

          myResult.push({ ok: result });
        }
      }

      // order with open_revs is unspecified
      leaves.forEach((leaf) => {
        api.get(id, {
          rev: leaf, // handled
          revs: opts.revs, // handled
          latest: opts.latest, // handled
          attachments: opts.attachments,
          binary: opts.binary
        }, function (err, doc) {
          if (!err) {
            // using latest=true can produce duplicates
            var existing;
            for (var i = 0, l = result.length; i < l; i++) {
              if (result[i].ok && result[i].ok._rev === doc._rev) {
                existing = true;
                break;
              }
            }
            if (!existing) {
              result.push({ok: doc});
            }
          } else {
            result.push({missing: leaf});
          }
          count--;
          if (!count) {
            const myJson = JSON.stringify(myResult);
            const oldJson = JSON.stringify(result);
            if (myJson !== oldJson) {
              console.log('@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@');
              console.log('@');
              console.log('@ finishOpenRevs()', '         myResult:', myJson);
              console.log('@ finishOpenRevs()', 'returning: result:', oldJson);
              console.log('@');
              console.log('@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@');
            }
            cb(null, result);
          }
        });
      });
    };

    if (opts.open_revs) {
      api._openTransactionSafely([DOC_STORE], 'readonly', function (err, txn) {
        txn.onabort = function () {
          cb(createError(UNKNOWN_ERROR, 'transaction was aborted'));
        };
        txn.ontimeout = idbError(cb);
        var req = txn.objectStore(DOC_STORE).get(id);
        req.onsuccess = function (e) {
          mySpecialDoc = e.target.result;
          const { rev_tree } = mySpecialDoc;
          if (opts.open_revs === "all") {
            leaves = collectLeaves(rev_tree).map(function (leaf) {
              return leaf.rev;
            });
            finishOpenRevs();
          } else {
            if (Array.isArray(opts.open_revs)) {
              leaves = opts.open_revs;
              for (var i = 0; i < leaves.length; i++) {
                var l = leaves[i];
                // looks like it's the only thing couchdb checks
                if (!(typeof (l) === "string" && /^\d+-/.test(l))) {
                  return cb(createError(INVALID_REV));
                }
              }
              finishOpenRevs();
            } else {
              return cb(createError(UNKNOWN_ERROR, 'function_clause'));
            }
          }
        };
      });
      return; // open_revs does not like other options
    }

    return api._get(id, opts, (err, result) => {
      if (err) {
        err.docId = id;
        return cb(err);
      }

      var doc = result.doc;
      var metadata = result.metadata;
      var ctx = result.ctx;

      if (opts.conflicts) {
        var conflicts = collectConflicts(metadata);
        if (conflicts.length) {
          doc._conflicts = conflicts;
        }
      }

      if (isDeleted(metadata, doc._rev)) {
        doc._deleted = true;
      }

      // TODO use processRevsRevsInfo()
      if (opts.revs || opts.revs_info) {
        var splittedRev = doc._rev.split('-');
        var revNo       = parseInt(splittedRev[0], 10);
        var revHash     = splittedRev[1];

        var paths = rootToLeaf(metadata.rev_tree);
        var path = null;

        for (var i = 0; i < paths.length; i++) {
          var currentPath = paths[i];
          var hashIndex = currentPath.ids.map(function (x) { return x.id; })
            .indexOf(revHash);
          var hashFoundAtRevPos = hashIndex === (revNo - 1);

          if (hashFoundAtRevPos || (!path && hashIndex !== -1)) {
            path = currentPath;
          }
        }

        /* istanbul ignore if */
        if (!path) {
          err = new Error('invalid rev tree');
          err.docId = id;
          return cb(err);
        }

        var indexOfRev = path.ids.map(function (x) { return x.id; })
          .indexOf(doc._rev.split('-')[1]) + 1;
        var howMany = path.ids.length - indexOfRev;
        path.ids.splice(indexOfRev, howMany);
        path.ids.reverse();

        if (opts.revs) {
          doc._revisions = {
            start: (path.pos + path.ids.length) - 1,
            ids: path.ids.map(function (rev) {
              return rev.id;
            })
          };
        }
        if (opts.revs_info) {
          var pos =  path.pos + path.ids.length;
          doc._revs_info = path.ids.map(function (rev) {
            pos--;
            return {
              rev: pos + '-' + rev.id,
              status: rev.opts.status
            };
          });
        }
      }

      if (opts.attachments && doc._attachments) {
        var attachments = doc._attachments;
        var count = Object.keys(attachments).length;
        if (count === 0) {
          return cb(null, doc);
        }
        Object.keys(attachments).forEach((key) => {
          api._getAttachment(doc._id, key, attachments[key], {
            // Previously the revision handling was done in adapter.js
            // getAttachment, however since idb-next doesnt we need to
            // pass the rev through
            rev: doc._rev,
            binary: opts.binary,
            metadata: metadata,
            ctx: ctx
          }, function (err, data) {
            var att = doc._attachments[key];
            att.data = data;
            delete att.stub;
            delete att.length;
            if (!--count) {
              cb(null, doc);
            }
          });
        });
      } else {
        if (doc._attachments) {
          for (var key in doc._attachments) {
            /* istanbul ignore else */
            if (Object.prototype.hasOwnProperty.call(doc._attachments, key)) {
              doc._attachments[key].stub = true;
            }
          }
        }
        cb(null, doc);
      }
    });
  }).bind(api);

  // TODO: this setTimeout seems nasty, if its needed lets
  // figure out / explain why
  setTimeout(function () {
    callback(null, api);
  });
}

// TODO: this isnt really valid permanently, just being lazy to start
IndexeddbPouch.valid = function () {
  return true;
};

export default function (PouchDB) {
  PouchDB.adapter(ADAPTER_NAME, IndexeddbPouch, true);
}
